from collections import Counter

class Solution:
  def findXSum(self, nums: list[int], k: int, x: int) -> list[int]:
    counts = Counter()
    answer = []
    for i, value in enumerate(nums):
      counts[value] += 1
      if i >= k:
        outgoing = nums[i - k]
        counts[outgoing] -= 1
        if counts[outgoing] == 0:
          del counts[outgoing]
      if i >= k - 1:
        top = sorted(counts.items(), key=lambda item: (item[1], item[0]), reverse=True)[:x]
        answer.append(sum(value * frequency for value, frequency in top))
    return answer
